package com.courier.tracking.service;
import com.courier.tracking.dsa.*;import com.courier.tracking.model.*;import org.springframework.stereotype.Service;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class CourierService {
 private final PackageBST bst=new PackageBST();private final CourierGraph graph=new CourierGraph();private final DateTimeFormatter fmt=DateTimeFormatter.ofPattern("dd MMM yyyy, hh:mm a");
 public CourierService(){graph.addRoute("Delhi","Noida",20);graph.addRoute("Delhi","Agra",230);graph.addRoute("Noida","Agra",200);graph.addRoute("Noida","Lucknow",500);graph.addRoute("Agra","Kanpur",280);graph.addRoute("Kanpur","Lucknow",80);seed("CT1001","Aarav Sharma","Riya Verma","Delhi","Lucknow","Noida","In Transit");seed("CT1002","Kabir Singh","Ananya Gupta","Agra","Kanpur","Agra","Dispatched");seed("CT1003","Meera Joshi","Ishaan Patel","Noida","Delhi","Noida","Out for Delivery");}
 private String now(){return LocalDateTime.now().format(fmt);} private void seed(String id,String s,String r,String o,String d,String loc,String st){CourierPackage p=new CourierPackage(id,s,r,o,d,loc,st);JourneyLinkedList h=new JourneyLinkedList();h.add(new JourneyEvent("Package Registered",o,now()));h.add(new JourneyEvent(st,loc,now()));p.setHistory(h.toList());route(p);bst.insert(p);}
 private void route(CourierPackage p){var r=graph.shortestRoute(p.getOrigin(),p.getDestination());p.setShortestRoute(r.path());p.setRouteDistance(r.distance());}
 public synchronized List<CourierPackage> all(){return bst.inOrder();} public synchronized CourierPackage find(String id){CourierPackage p=bst.search(id);if(p!=null)route(p);return p;}
 public synchronized CourierPackage add(CourierPackage p){if(blank(p.getTrackingId()))throw new IllegalArgumentException("Tracking ID is required.");if(bst.search(p.getTrackingId())!=null)throw new IllegalArgumentException("Tracking ID already exists.");if(blank(p.getOrigin())||blank(p.getDestination()))throw new IllegalArgumentException("Origin and destination are required.");if(blank(p.getStatus()))p.setStatus("Package Registered");if(blank(p.getCurrentLocation()))p.setCurrentLocation(p.getOrigin());JourneyLinkedList h=new JourneyLinkedList();h.add(new JourneyEvent("Package Registered",p.getOrigin(),now()));p.setHistory(h.toList());route(p);bst.insert(p);return p;}
 public synchronized CourierPackage update(String id,String status,String loc){CourierPackage p=bst.search(id);if(p==null)return null;if(!blank(status))p.setStatus(status);if(!blank(loc))p.setCurrentLocation(loc);p.getHistory().add(new JourneyEvent(p.getStatus(),p.getCurrentLocation(),now()));route(p);return p;}
 private boolean blank(String s){return s==null||s.isBlank();}
}
